document.addEventListener('DOMContentLoaded', function() {
  const searchInput = document.getElementById('user-search');
  const checkboxes = document.querySelectorAll('.user-checkbox');

  function filterUsers() {
    const searchTerm = searchInput.value.toLowerCase();

    checkboxes.forEach(function(checkbox) {
      const label = checkbox.closest('.user-checkbox-item');
      const userName = label.querySelector('.user-name').textContent.toLowerCase();
      const userEmail = label.querySelector('.user-email').textContent.toLowerCase();

      // Show if name or email contains search term
      if (userName.includes(searchTerm) || userEmail.includes(searchTerm)) {
        label.style.display = 'flex';
      } else {
        label.style.display = 'none';
      }
    });
  }

  searchInput.addEventListener('input', filterUsers);
});

